func (s *EmailService) Footprint(ctx context.Context, params *EmailFootprintParams, opts ...RequestOption) (*EmailFootprint, error) {
	return doCall[EmailFootprint](ctx, s.t, &call{method: http.MethodPost, path: "/v1/email/footprint", body: params, envelope: envelopeData}, opts)
}

