// PhoneService holds the phone APIs: Lookup and Otp (a resource).
type PhoneService struct {
	// Otp holds the phone.otp APIs: Send and Check.
	Otp *PhoneOtpService

	t *transport
}

// Lookup calls Phone Intelligence: POST /v1/phone/lookup.
//
// Whether a number is valid and live, with its format, country, line type, carrier, SMS pumping risk, SIM swap and forwarding, and a risk level. With a name, the carrier is also asked whether the number belongs to that person.
//
// Price: 0.08 credits per successful call.
func (s *PhoneService) Lookup(ctx context.Context, params *PhoneLookupParams, opts ...RequestOption) (*PhoneLookup, error) {
	return doCall[PhoneLookup](ctx, s.t, &call{method: http.MethodPost, path: "/v1/phone/lookup", body: params, envelope: envelopeData}, opts)
}

// PhoneOtpService holds the phone.otp APIs: Send and Check.
type PhoneOtpService struct {
	t *transport
}

// Send calls Send Phone Code: POST /v1/phone/otp/send.
//
// Sends a one-time code by SMS to prove the person holds the number.
