// Price: 0.8 credits per successful call.
func (s *ScreeningService) Sanctions(ctx context.Context, params *ScreeningSanctionsParams, opts ...RequestOption) (*ScreeningSanctions, error) {
	return doCall[ScreeningSanctions](ctx, s.t, &call{method: http.MethodPost, path: "/v1/screen/sanctions", body: params, envelope: envelopeData}, opts)
}

// Crypto calls Wallet Screening: POST /v1/screen/crypto.
//
// A verdict and a risk level for up to 100 wallet addresses, on any supported network, from sanctions and illicit-activity data.
