func (s *ScreeningService) Crypto(ctx context.Context, params *ScreeningCryptoParams, opts ...RequestOption) (*ScreeningCrypto, error) {
	return doCall[ScreeningCrypto](ctx, s.t, &call{method: http.MethodPost, path: "/v1/screen/crypto", body: params, envelope: envelopeData}, opts)
}

