// ContactService holds the contact APIs: Dossier.
type ContactService struct {
	t *transport
}

// Dossier calls Contact Dossier: POST /v1/verify/contact.
//
// Everything in one call: email, phone, IP, sanctions screening and wallet, each part in exactly the same shape as its own API. The slower checks (accounts, username, adverse media) are opt-in.
//
// Price: 1.39 credits per successful call.
func (s *ContactService) Dossier(ctx context.Context, params *ContactDossierParams, opts ...RequestOption) (*ContactDossier, error) {
	return doCall[ContactDossier](ctx, s.t, &call{method: http.MethodPost, path: "/v1/verify/contact", body: params, envelope: envelopeData}, opts)
}

// ChequesService holds the cheques APIs: Read, Micr, MicrLine, Amount, Date, Parties and Bank.
type ChequesService struct {
	t *transport
}

// Read calls Read a whole cheque: POST /v2/cheques/read.
//
// Reads everything on a cheque in one call: the MICR line with its named fields, what is written on the face (payee, amount in figures and words, date, drawer, bank, crossing, signature), the bank matched in the directory, and the country and currency. A photo with several cheques returns each in `cheques`. The read and the photo are kept in the scan history.
//
// Price: 0.05 credits per successful call.
func (s *ChequesService) Read(ctx context.Context, params *ChequeReadParams, opts ...RequestOption) (*ChequeDeepRead, error) {
	return doCall[ChequeDeepRead](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cheques/read", form: params, source: true, envelope: envelopeObject}, opts)
}

// Micr calls Read a cheque's MICR line: POST /v2/cheques/micr.
//
// Finds and reads every MICR code line on a cheque (E-13B or CMC-7) and names its fields: the layout template for the layout, a national standard when one applies (Canada, India), and the US routing-number proof. The read and the photo are kept in the scan history.
//
// Price: 0.02 credits per successful call.
func (s *ChequesService) Micr(ctx context.Context, params *ChequeMicrParams, opts ...RequestOption) (*ChequeResponse, error) {
	return doCall[ChequeResponse](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cheques/micr", form: params, source: true, envelope: envelopeObject}, opts)
}

// MicrLine calls Read just the MICR line: POST /v2/cheques/micr-line.
//
// Reads the strongest MICR line with the same engine and naming as the full reads and returns a small response: the line, its named fields, its layout and confidence. Nothing is stored.
//
// Price: 0.02 credits per successful call.
func (s *ChequesService) MicrLine(ctx context.Context, params *ChequeMicrLineParams, opts ...RequestOption) (*MicrLine, error) {
	return doCall[MicrLine](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cheques/micr-line", form: params, source: true, envelope: envelopeObject}, opts)
}

// Amount calls Read a cheque's amount: POST /v2/cheques/amount.
//
// Reads the amount in figures and in words, turns it into a number, says whether the two agree, and resolves the currency. Nothing is stored.
//
// Price: 0.02 credits per successful call.
func (s *ChequesService) Amount(ctx context.Context, params *ChequeAmountParams, opts ...RequestOption) (*ChequeAmount, error) {
	return doCall[ChequeAmount](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cheques/amount", form: params, source: true, envelope: envelopeObject}, opts)
}

// Date calls Read a cheque's date: POST /v2/cheques/date.
//
// Reads the cheque's date as written and as YYYY-MM-DD, with its age in days (negative when post-dated). Nothing is stored.
//
// Price: 0.02 credits per successful call.
func (s *ChequesService) Date(ctx context.Context, params *ChequeDateParams, opts ...RequestOption) (*ChequeDate, error) {
	return doCall[ChequeDate](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cheques/date", form: params, source: true, envelope: envelopeObject}, opts)
}

// Parties calls Read a cheque's payee and drawer: POST /v2/cheques/parties.
//
// Reads who the cheque is paid to (the name after Pay) and whose account pays it (the account holder printed on the cheque). Nothing is stored.
//
// Price: 0.02 credits per successful call.
func (s *ChequesService) Parties(ctx context.Context, params *ChequePartiesParams, opts ...RequestOption) (*ChequeParties, error) {
	return doCall[ChequeParties](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cheques/parties", form: params, source: true, envelope: envelopeObject}, opts)
}

// Bank calls Read a cheque's bank: POST /v2/cheques/bank.
//
// Reads the bank printed on the cheque and matches it in the directory of about 75,000 banks. A bank not in the directory is never forced onto another: `bank` is left out. Nothing is stored.
//
// Price: 0.02 credits per successful call.
func (s *ChequesService) Bank(ctx context.Context, params *ChequeBankParams, opts ...RequestOption) (*ChequeBank, error) {
	return doCall[ChequeBank](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cheques/bank", form: params, source: true, envelope: envelopeObject}, opts)
}

// BanksService holds the banks APIs: Lookup.
type BanksService struct {
	t *transport
}

// Lookup calls Look up a bank: GET /v2/banks.
//
// Finds a bank in the directory by BIC, or by name (best with the country). Trust `bank` when `verified` is true; otherwise look at `alternatives`. Send `name` or `bic`; neither answers `400 missing_query`.
//
// Price: 0.002 credits per successful call.
func (s *BanksService) Lookup(ctx context.Context, params *BankLookupParams, opts ...RequestOption) (*BankLookup, error) {
	return doCall[BankLookup](ctx, s.t, &call{method: http.MethodGet, path: "/v2/banks", query: params, envelope: envelopeObject}, opts)
}

// CardsService holds the cards APIs: Read, Number, Expiry, Check and Fingerprint.
type CardsService struct {
	t *transport
}

// Read calls Read a payment card: POST /v2/cards/read.
//
// Reads every card in a photo: number, expiry and holder with their confidences, the checks (Luhn, length for the network, expiry), the BIN record and the issuer in the bank directory. The full number is in this response only; the stored copy keeps the first six and last four digits, and the photo is never stored.
//
// Price: 0.03 credits per successful call.
func (s *CardsService) Read(ctx context.Context, params *CardReadParams, opts ...RequestOption) (*CardResponse, error) {
	return doCall[CardResponse](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cards/read", form: params, source: true, envelope: envelopeObject}, opts)
}

// Number calls Read a card number: POST /v2/cards/number.
//
// Reads the card number from a photo, with its network and checks. Nothing is stored.
//
// Price: 0.02 credits per successful call.
func (s *CardsService) Number(ctx context.Context, params *CardNumberParams, opts ...RequestOption) (*CardNumber, error) {
	return doCall[CardNumber](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cards/number", form: params, source: true, envelope: envelopeObject}, opts)
}

// Expiry calls Read a card's expiry date: POST /v2/cards/expiry.
//
// Reads the expiry date from a card photo and works out whether the card has expired and how many days it has left. Nothing is stored.
//
// Price: 0.02 credits per successful call.
func (s *CardsService) Expiry(ctx context.Context, params *CardExpiryParams, opts ...RequestOption) (*CardExpiry, error) {
	return doCall[CardExpiry](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cards/expiry", form: params, source: true, envelope: envelopeObject}, opts)
}

// Check calls Check a card number: POST /v2/cards/check.
//
// Checks a typed card number, for example from a checkout form: the Luhn checksum, a length that fits the network, the expiry when sent, and the BIN record. Accept the card when `scheme_valid` is true and `expired` is not. Only the first six and last four digits come back; nothing is stored.
//
// Price: 0.002 credits per successful call.
func (s *CardsService) Check(ctx context.Context, params *CardCheckParams, opts ...RequestOption) (*CardCheck, error) {
	return doCall[CardCheck](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cards/check", body: params, envelope: envelopeObject}, opts)
}

// Fingerprint calls Fingerprint a card number: POST /v2/cards/fingerprint.
//
// Turns a card number into a fingerprint: always the same for the same card, and impossible to turn back into the number. Store it to recognise a card you have seen before; a card read from a photo carries the same fingerprint.
//
// Price: 0.002 credits per successful call.
func (s *CardsService) Fingerprint(ctx context.Context, params *CardFingerprintParams, opts ...RequestOption) (*CardFingerprint, error) {
	return doCall[CardFingerprint](ctx, s.t, &call{method: http.MethodPost, path: "/v2/cards/fingerprint", body: params, envelope: envelopeObject}, opts)
}

// BinService holds the bin APIs: Lookup.
type BinService struct {
	t *transport
}

// Lookup calls Look up a BIN: GET /v2/bin/{digits}.
//
// Looks up the first 6 to 8 digits of a card: network, type, level, funding, issuer, country with its flag, currency, and the issuer's record in the bank directory. Fewer than 6 digits answer `400 bin_too_short`; a BIN not in the tables `404 bin_not_found`.
//
// Price: 0.002 credits per successful call.
func (s *BinService) Lookup(ctx context.Context, digits string, opts ...RequestOption) (*BinRecord, error) {
	path, err := buildPath("/v2/bin/{digits}", digits)
	if err != nil {
		return nil, err
	}
	return doCall[BinRecord](ctx, s.t, &call{method: http.MethodGet, path: path, envelope: envelopeObject}, opts)
}

